import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

handle_cleanup_pass = verify('handle_cleanup_pass', '''
    use core.http;
    fn main() -> i32 {
        let listener = http.bind()
        defer close(listener)
        return 0
    }
''', 0)
assert handle_cleanup_pass['errors'] == 0, handle_cleanup_pass

handle_cleanup_fail = verify('handle_cleanup_fail', '''
    use core.http;
    fn main() -> i32 {
        let listener = http.bind()
        return 0
    }
''', 1)
handle_cleanup_messages = messages(handle_cleanup_fail)
assert any('leaks allocation' in message and '`listener`' in message for message in handle_cleanup_messages), handle_cleanup_fail
assert any('linear value `listener` was not consumed/freed' in message for message in handle_cleanup_messages), handle_cleanup_fail

handle_match_cleanup_fail = verify('handle_match_cleanup_fail', '''
    use core.http;
    fn main() -> i32 {
        let listener = http.bind()
        match true {
            true => close(listener),
            _ => 0,
        }
        close(listener)
        return 0
    }
''', 1)
handle_match_messages = messages(handle_match_cleanup_fail)
assert any('divergent ownership state for `listener`' in message for message in handle_match_messages), handle_match_cleanup_fail
assert any('uses moved value `listener` after move/consume' in message for message in handle_match_messages), handle_match_cleanup_fail
assert any('consumes non-owned or already-consumed value `listener` via `close`' in message for message in handle_match_messages), handle_match_cleanup_fail

thread_borrow_fail = verify('thread_borrow_fail', '''
    async fn worker(v: &'a i32) -> &'a i32 {
        return v
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
thread_borrow_diag = find_message(thread_borrow_fail, 'returns borrowed reference across thread-capable boundary')
assert 'Send/Sync-safe handle' in (thread_borrow_diag.get('help') or ''), thread_borrow_diag
assert 'capability token parameters' not in (thread_borrow_diag.get('help') or ''), thread_borrow_diag

thread_mutable_fail = verify('thread_mutable_fail', '''
    async fn worker(v: &'a mut i32) -> i32 {
        discard v
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
thread_mutable_diag = find_message(thread_mutable_fail, 'requires Send/Sync-safe wrapper before thread crossing')
assert 'wrap mutable references/pointers' in (thread_mutable_diag.get('help') or ''), thread_mutable_diag
assert 'capability token parameters' not in (thread_mutable_diag.get('help') or ''), thread_mutable_diag

borrow_pass = verify('borrow_pass', '''
    fn borrow(v: &'a i32) -> &'a i32 {
        return v
    }
    fn main() -> i32 {
        return 0
    }
''', 0)
assert borrow_pass['errors'] == 0, borrow_pass
assert not any('thread-capable boundary' in message for message in messages(borrow_pass)), borrow_pass

plain_ptr_import_fail = verify('plain_ptr_import_fail', '''
    ext c fn c_write(ptr: *u8) -> i32;
    fn main() -> i32 {
        return 0
    }
''', 1)
plain_ptr_diag = find_message(plain_ptr_import_fail, 'must be declared `ext unsafe c fn`')
assert 'mark this import as `ext unsafe c fn`' in (plain_ptr_diag.get('help') or ''), plain_ptr_diag

callback_anchor_fail = verify('callback_anchor_fail', '''
    ext unsafe c fn register_callback(cb: fn(i32) -> i32, value: i32) -> i32;
    fn main() -> i32 {
        return 0
    }
''', 1)
callback_anchor_fail_diag = find_message(callback_anchor_fail, 'requires an adjacent `*_ctx` or `*_context` anchor')
assert 'neighboring context parameter' in (callback_anchor_fail_diag.get('help') or ''), callback_anchor_fail_diag

callback_anchor_pass = verify('callback_anchor_pass', '''
    ext unsafe c fn register_callback(cb: fn(i32) -> i32, cb_ctx: *u8, value: i32) -> i32;
    fn main() -> i32 {
        return 0
    }
''', 0)
assert callback_anchor_pass['errors'] == 0, callback_anchor_pass
assert not any('requires an adjacent `*_ctx` or `*_context` anchor' in message for message in messages(callback_anchor_pass)), callback_anchor_pass

print('compiler-verify-memory-surface-ok')

